void save(Object o, Path path, boolean asJson) throws IOException {
    if (asJson) {
        new ObjectMapper().writeValue(path.toFile(), o);
    } else {
        try (ObjectOutputStream oos = new ObjectOutputStream(new FileOutputStream(path.toFile()))) {
            oos.writeObject(o);
        }
    }
}

